contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Ensure c has some ether available so a successful sendMoney would be observable.
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk);

        uint beforeBalance = address(c).balance;
        address nonOwner = address(0xdead);

        bool reverted;
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("sendMoney(address,uint256)", nonOwner, uint(0))
        );
        reverted = !success;

        uint afterBalance = address(c).balance;

        assert(reverted && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

