contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint amount, uint dcount) public payable {
        // setup: make msg.sender the owner and set a deposits count
        c = C(address(c));
        require(address(this) == c.owner(), "caller must be owner");

        // read before values
        uint beforeTarget = target.balance;
        uint beforeC = address(c).balance;

        // perform the state-changing call, capture success in a variable via low-level try/catch pattern
        bool ok;
        ok = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, amount));

        // read after values
        uint afterTarget = target.balance;
        uint afterC = address(c).balance;

        // general rule: conservation of ether sum (target + contract)
        assert(afterTarget + afterC == beforeTarget + beforeC);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, uint value) public payable {
        require(msg.sender != c.owner(), "caller must be non-owner");
        require(address(this).balance >= value, "insufficient balance");

        uint balBefore = address(c).balance;

        bool withdrew;
        try c.withdraw(value) { withdrew = false; } catch { withdrew = true; }
        assert(withdrew && address(c).balance == balBefore);

        bool withdrewAll;
        try c.withdrawAll() { withdrewAll = false; } catch { withdrewAll = true; }
        assert(withdrewAll && address(c).balance == balBefore);

        bool sent;
        try c.sendMoney{value: value}(target, value) { sent = false; } catch { sent = true; }
